export function omitted(flag: bool): i32 { let value: i32 = 1; if (flag) { value = 2; } return value; }
export function empty(flag: bool): i32 { let value: i32 = 1; if (flag) { value = 2; } else { } return value; }
export function oneArm(flag: bool): i32 { if (flag) { return 1; } return 2; }
export function bothArms(flag: bool): i32 { if (flag) { return 1; } else { return 2; } }
export function loop(n: i32): i32 { let value: i32 = 0; while (value < n) { value = value + 1; } return value; }
export function nested(flag: bool, n: i32): i32 { let value: i32 = 0; while (value < n) { if (flag) { value = value + 1; } else { value = n; } } return value; }
